import chalk5 from "chalk";
var syncMock = async () => {
  try {
    console.log(chalk5.yellow("Checking if mock data..."));
    const existingCitys = await city_model_default.find();
    if (existingCitys.length === citysMock.length) {
      console.log(chalk5.green("Data is match, no need to insert mock data."));
      return;
    }
    console.warn(chalk5.yellow("Data isn't match, inserting mock data..."));
    await city_model_default.deleteMany();
    console.info(chalk5.yellow("Deleted all data."));
    await city_model_default.insertMany(AbruzzoCityMock);
    await city_model_default.insertMany(BasilicataCityMock);
    await city_model_default.insertMany(CalabriaCityMock);
    await city_model_default.insertMany(CampaniaCityMock);
    await city_model_default.insertMany(EmiliaRomagnaCityMock);
    await city_model_default.insertMany(FriuliVeneziaGiuliaCityMock);
    await city_model_default.insertMany(LazioCityMock);
    await city_model_default.insertMany(LiguriaCityMock);
    await city_model_default.insertMany(LombardiaCityMock);
    await city_model_default.insertMany(MarcheCityMock);
    await city_model_default.insertMany(MoliseCityMock);
    await city_model_default.insertMany(PiemonteCityMock);
    await city_model_default.insertMany(PugliaCityMock);
    await city_model_default.insertMany(SardegnaCityMock);
    await city_model_default.insertMany(SiciliaCityMock);
    await city_model_default.insertMany(ToscanaCityMock);
    await city_model_default.insertMany(TrentinoAltoAdigeCityMock);
    await city_model_default.insertMany(UmbriaCityMock);
    await city_model_default.insertMany(ValleDAostaCityMock);
    await city_model_default.insertMany(VenetoCityMock);
    console.log(chalk5.green("Mock data inserted."));
  } catch (error) {
    console.error(chalk5.red("Error inserting mock data", error));
    process.exit(1);
  }
};
var syncMock_default = syncMock;

